import java.util.Arrays;

public class Lat {
    static long spin(long nanos) {
        long end = System.nanoTime() + nanos;
        long x = 0;
        while (System.nanoTime() < end) { x++; }
        return x;
    }

    public static void main(String[] a) throws Exception {
        int n = 150;
        long[] lat = new long[n];
        for (int i = 0; i < n; i++) {
            long t0 = System.nanoTime();
            spin(10_000_000L);                 // 10 ms of CPU work
            lat[i] = (System.nanoTime() - t0) / 1_000_000;
        }
        Arrays.sort(lat);
        System.out.printf("requests=%d p50=%dms p99=%dms max=%dms%n",
            n, lat[n / 2], lat[(int) (n * 0.99)], lat[n - 1]);
    }
}

#include <stdio.h>
#include <errno.h>
#include <string.h>
#include <stddef.h>
#include <sys/stat.h>
#include <sys/prctl.h>
#include <sys/syscall.h>
#include <linux/seccomp.h>
#include <linux/filter.h>
#include <linux/audit.h>

int main(void) {
    struct sock_filter f[] = {
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, arch)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, AUDIT_ARCH_X86_64, 1, 0),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_KILL_PROCESS),
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_mkdir, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ERRNO | EPERM),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
    };
    struct sock_fprog p = { sizeof f / sizeof f[0], f };
    printf("before: mkdir -> %d (%s)\n", mkdir("/tmp/osw_o6/d1", 0755), strerror(errno));
    prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);
    if (prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &p)) { perror("seccomp"); return 1; }
    errno = 0;
    int r = mkdir("/tmp/osw_o6/d2", 0755);
    printf("after:  mkdir -> %d (%s)\n", r, strerror(errno));
    FILE *s = fopen("/proc/self/status", "r");
    char l[256];
    while (fgets(l, sizeof l, s)) if (!strncmp(l, "Seccomp", 7)) fputs(l, stdout);
    return 0;
}

public class Graceful {
    public static void main(String[] args) throws Exception {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.out.println("hook: SIGTERM received, draining in-flight work");
            try { Thread.sleep(300); } catch (InterruptedException e) { }
            System.out.println("hook: drained, exiting");
        }));
        System.out.println("started pid=" + ProcessHandle.current().pid());
        while (true) { Thread.sleep(1000); }
    }
}

import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.util.ArrayList;
import java.util.List;

public class Backlog {
    public static void main(String[] a) throws Exception {
        int backlog = Integer.parseInt(a[0]);
        InetAddress lo = InetAddress.getLoopbackAddress();
        ServerSocket ss = new ServerSocket(20601, backlog, lo);
        List<Socket> cs = new ArrayList<>();
        int ok = 0, fail = 0;
        for (int i = 0; i < 20; i++) {          // the server never calls accept()
            Socket s = new Socket();
            try {
                s.connect(new InetSocketAddress(lo, 20601), 1000);
                ok++;
                cs.add(s);
            } catch (SocketTimeoutException e) { fail++; }
        }
        System.out.println("backlog=" + backlog + " connected=" + ok + " timed_out=" + fail);
        Thread.sleep(300);
    }
}

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;

public class Jwt {
    public static void main(String[] a) {
        Instant issuedAt = Instant.parse("2026-10-18T10:00:00Z");   // set by the auth server
        Instant exp = issuedAt.plusSeconds(300);                      // valid for 5 minutes
        for (long skew : new long[] {0, -90, 120, 400}) {
            Clock clk = Clock.offset(Clock.fixed(issuedAt.plusSeconds(10), ZoneOffset.UTC),
                                     Duration.ofSeconds(skew));
            Instant now = clk.instant();
            boolean notYet = now.isBefore(issuedAt);
            boolean expired = now.isAfter(exp);
            System.out.printf("resource-server clock skew %+5ds: now=%s -> %s%n", skew, now,
                notYet ? "REJECT (token used before iat/nbf)"
                       : expired ? "REJECT (expired)" : "accept");
        }
    }
}
